from rdkit import Chem
from rdkit.Chem import AllChem
from Bio.PDB import PDBParser
from pathlib import Path
import math

# Read reference ligand coordinates from SDF
mol = Chem.SDMolSupplier('/workspace/reference.sdf', removeHs=False)[0]
conf = mol.GetConformer()
lig_coords = {i: conf.GetAtomPosition(i) for i in range(mol.GetNumAtoms())}

# Parse PDB, collect hetero residues and nearby contacts to ligand atoms
parser = PDBParser(QUIET=True)
structure = parser.get_structure('x', '/workspace/complex.pdb')
model = next(structure.get_models())

# list hetero residues
hets = []
for chain in model:
    for res in chain:
        hetflag = res.id[0]
        if hetflag.strip() != '':
            hets.append((chain.id, res.resname, res.id))
print('Hetero residues sample:', hets[:20], 'count', len(hets))

# Find likely ligand residue by atom count / proximity to SDF centroid
cent = [sum(lig_coords[i][j] for i in lig_coords)/len(lig_coords) for j in range(3)]
print('SDF centroid', cent)
lig_candidates=[]
for chain in model:
    for res in chain:
        if res.id[0].strip() != '':
            atoms=[a for a in res.get_atoms() if a.element != 'H']
            if not atoms: continue
            rc=[sum(a.coord[j] for a in atoms)/len(atoms) for j in range(3)]
            d=math.dist(cent,rc)
            lig_candidates.append((d, chain.id, res.resname, res.id, len(atoms), rc))
for x in sorted(lig_candidates)[:10]:
    print('cand',x)

# choose closest hetero residue with >10 atoms
closest = sorted([x for x in lig_candidates if x[4]>10])[0]
print('chosen', closest)
_, ch, resname, resid, _, _ = closest
res = model[ch][resid]
res_atoms=[a for a in res.get_atoms() if a.element!='H']

# contacts from pocket residues only
pocket = {('A',20),('A',21),('A',22),('A',23),('A',24),('A',25),('A',26),('A',27),('A',30),('A',61),('A',62),('A',63),('A',64),('A',65),('A',66),('A',67),('A',68),('A',69),('A',134),('A',135),('A',136),('A',138),('A',139),('A',140),('A',143),('A',144),('A',161),('A',162),('A',163),('A',164),('A',165),('A',184),('A',185),('A',210)}
protein_atoms=[]
for chain in model:
    for res2 in chain:
        if (chain.id,res2.id[1]) in pocket:
            for a in res2.get_atoms():
                if a.element!='H':
                    protein_atoms.append((chain.id,res2.resname,res2.id[1],a))

contacts=[]
for la in res_atoms:
    for ch2,resn,resseq,pa in protein_atoms:
        d = ((la.coord-pa.coord)**2).sum()**0.5
        if d<4.2:
            contacts.append((d, la.name, ch2,resn,resseq,pa.name))
for c in sorted(contacts)[:120]:
    print(c)
print('ncontacts', len(contacts))

